//! Records copied from a real Altium board, to be patched: the parts of these
//! that Coppersmith has no meaning for are kept as Altium wrote them (the
//! unique ids inside are cleared when they're used). Each is one record's
//! bytes, as hex.

/// A via: 321 bytes.
pub const VIA: &str = "";
/// A surface-mount pad's geometry: 202 bytes.
pub const PAD: &str = "";
/// A text record: 252 bytes.
pub const TEXT: &str = "";

pub fn bytes(hex: &str) -> Vec<u8> {
    (0..hex.len() / 2).map(|i| u8::from_str_radix(&hex[2 * i..2 * i + 2], 16).unwrap_or(0)).collect()
}
